// Parse each Drive trigger payload — extract { file_id, lesson_id, filename, mime_type }.
// Iterates over ALL input items so multi-file drops produce one output item per file.
// lesson_id is derived from filename (e.g., 'sleep_002.mp3' → 'sleep_002').
const out = [];
for (const i of $input.all()) {
  const item = i.json || {};
  const filename = item.name || '';
  const file_id = item.id;
  const mime_type = item.mimeType || '';

  if (!file_id || !filename) {
    console.warn('Drive trigger payload missing id/name — skipping:', JSON.stringify(item));
    continue;
  }

  // Strip extension and sanitize for use as a sheet/file key.
  const baseName = filename.replace(/\.[^./\\]+$/, '');
  const lesson_id = baseName.trim().toLowerCase().replace(/[^a-z0-9_-]+/g, '_').replace(/^_+|_+$/g, '');
  if (!lesson_id) {
    console.warn('Could not derive lesson_id from filename — skipping:', filename);
    continue;
  }

  // Sanity: skip non-audio files (Drive trigger may fire on any file dropped in the folder).
  const looksAudio = /^audio\//.test(mime_type) || /\.(mp3|wav|m4a|aac|flac|ogg|opus)$/i.test(filename);
  if (!looksAudio) {
    console.warn('Skipping non-audio file:', filename, mime_type);
    continue;
  }

  out.push({ json: { file_id, lesson_id, filename, mime_type } });
}
return out;

// Collapse N Parse Filename items down to 1 sentinel item so the archive chain
// (List → Plan → Move) fires exactly once per Drive Trigger activation, not once
// per dropped file. Carries the set of just-dropped file IDs so Archive Previous Run
// can exclude them from the move list.
const newFileIds = $('Parse Filename').all().map(i => i.json.file_id).filter(Boolean);
const newFileNames = $('Parse Filename').all().map(i => i.json.filename).filter(Boolean);
return [{ json: { archive_run_at: new Date().toISOString(), new_file_ids: newFileIds, new_file_names: newFileNames } }];

// Plan Sources — emits one item per source folder that downstream List Files
// will hit via Drive REST. We dedupe folder IDs (in case fallback chains collapsed
// vtt → full → segments onto the same folder) so we don't list the same folder
// twice. drive_archive_folder_id is validated here, BEFORE any List/Move starts.
const cfg = {};
$('Read Config (Archive)').all().forEach(i => { if (i.json && i.json.key) cfg[i.json.key] = i.json.value; });

const ARCHIVE_PARENT = cfg.drive_archive_folder_id;
if (!ARCHIVE_PARENT) {
  throw new Error('drive_archive_folder_id missing from config sheet — required for the archive feature. Either set it to the Drive folder ID of 05_archive, or remove the archive chain from W_Master.');
}
if (!cfg.drive_input_folder_id) throw new Error('drive_input_folder_id missing from config sheet');
if (!cfg.drive_output_folder_id) throw new Error('drive_output_folder_id missing from config sheet');

const sources = [
  { src_key: '01_input',    folder_id: cfg.drive_input_folder_id },
  { src_key: '02_output', folder_id: cfg.drive_output_folder_id },
  { src_key: '03_full',     folder_id: cfg.drive_output_full_folder_id || cfg.drive_output_folder_id },
  { src_key: '04_vtt',      folder_id: cfg.drive_output_vtt_folder_id || cfg.drive_output_full_folder_id || cfg.drive_output_folder_id },
];

const seen = new Set();
const out = [];
for (const s of sources) {
  if (!s.folder_id || seen.has(s.folder_id)) continue;
  seen.add(s.folder_id);
  out.push({ json: { src_key: s.src_key, folder_id: s.folder_id, q: `'${s.folder_id}' in parents and trashed = false` } });
}
return out;

// Plan Archive — aggregates the per-source-folder file lists, filters out the
// just-dropped trigger files, derives the archive subfolder name, and emits a
// single plan item that downstream nodes consume via $('Plan Archive').first().json.
// If nothing remains to archive (first run / pre-cleaned folders) → emits a single
// item with skip=true and Has Files? routes around the destructive chain.
const FOLDER_MIME = 'application/vnd.google-apps.folder';

const sources = $('Plan Sources').all().map(i => i.json);
const responses = $('List Files').all().map(i => i.json);

if (sources.length !== responses.length) {
  console.warn(`[Archive] source/response count mismatch: ${sources.length} vs ${responses.length}`);
}

const newFileIds = new Set(($('Once Per Run').first().json.new_file_ids || []));

const cfg = {};
$('Read Config (Archive)').all().forEach(i => { if (i.json && i.json.key) cfg[i.json.key] = i.json.value; });

const toMove = [];
for (let i = 0; i < sources.length; i++) {
  const src = sources[i];
  const files = (responses[i] && responses[i].files) || [];
  for (const f of files) {
    if (f.mimeType === FOLDER_MIME) continue;       // never move subfolders
    if (newFileIds.has(f.id)) continue;             // skip just-dropped trigger files
    toMove.push({ id: f.id, name: f.name, src_key: src.src_key, src_folder: src.folder_id });
  }
}

if (toMove.length === 0) {
  console.log('[Archive] nothing to archive — folders already clean (first run or operator pre-cleaned)');
  return [{ json: { skip: true } }];
}

function basenameNoExt(name) { return (name || '').replace(/\.[^./\\]+$/, ''); }
let archiveBase = null;
const leftoverInputs = toMove.filter(f => f.src_key === '01_input').sort((a, b) => a.name.localeCompare(b.name));
if (leftoverInputs.length > 0) {
  archiveBase = basenameNoExt(leftoverInputs[0].name);
} else {
  const sample = toMove.find(f => /_(seg|full)_/.test(f.name));
  if (sample) archiveBase = sample.name.split(/_(seg|full)_/)[0];
}
if (!archiveBase) archiveBase = 'archive';

// Kyiv local time. 'sv-SE' locale → "YYYY-MM-DD HH:MM:SS"; turn into filename-safe
// "YYYY-MM-DD_HH-MM" (no seconds, underscore between date and time, hyphens not colons).
const kyivTime = new Date().toLocaleString('sv-SE', { timeZone: 'Europe/Kyiv' });
const stamp = kyivTime.replace(' ', '_').replace(/:/g, '-').slice(0, 16);
const archive_name = `${archiveBase}_${stamp}`;

const SHEET_ID = cfg.sheets_document_id || '1LAxDWyV0pAxM1s5W00PTJ7OvFNQUxoeMSuszuOz3lDU';
const ARCHIVE_PARENT = cfg.drive_archive_folder_id;

console.log(`[Archive] plan: ${toMove.length} files → ${archive_name}/ (parent ${ARCHIVE_PARENT})`);

return [{ json: { skip: false, archive_name, archive_parent: ARCHIVE_PARENT, sheet_id: SHEET_ID, files: toMove } }];

// Plan Settings Carryover — first node of the settings carry-over chain that fixes the
// archive snapshot's settings tabs. See DECISIONS ARCHIVE_SNAPSHOT_SETTINGS_CARRYOVER.
//
// THE BUG: Copy Sheet Snapshot runs at the START of the NEW run, so the snapshot's
// config/voices/prompts tabs hold the settings the operator already entered for the NEW run
// — not the run being archived. (segments/localizations are still the previous run's — they
// get cleared only later — so DATA is correct; only the settings tabs are wrong.)
//
// THE FIX: keep a standing JSON carry-over file in the archive parent folder holding the
// CURRENTLY-EXECUTING run's settings. Each archive step (a) overwrites the fresh snapshot's
// settings tabs from the carry-over (= the PREVIOUS run's settings), then (b) rewrites the
// carry-over with the current live settings for the NEXT archive to consume.
//
// Best-effort: every node in this chain has onError=continueRegularOutput and the code never
// throws, so any Drive/Sheets hiccup just leaves the snapshot with live settings (today's
// behaviour) and the run proceeds — no data loss, no halt before the W1/W2/W3 fan-out.
const plan = $('Plan Archive').first().json;
const snap = $('Copy Sheet Snapshot').first().json || {};

const SETTING_TABS = ['config', 'voices', 'prompts'];
const RANGES = { config: 'config!A:B', voices: 'voices!A:Z', prompts: 'prompts!A:C' };
const CARRYOVER_NAME = '_run_settings_carryover.json';

const liveSheetId = plan.sheet_id;
const snapshotId = snap.id || null;
const archiveParent = plan.archive_parent;
const enc = encodeURIComponent;

const live_batchget_url =
  `https://sheets.googleapis.com/v4/spreadsheets/${liveSheetId}/values:batchGet?` +
  SETTING_TABS.map((t) => `ranges=${enc(RANGES[t])}`).join('&') + '&majorDimension=ROWS';

const q = `name = '${CARRYOVER_NAME}' and '${archiveParent}' in parents and trashed = false`;
const find_url =
  `https://www.googleapis.com/drive/v3/files?q=${enc(q)}` +
  `&orderBy=${enc('createdTime desc')}&fields=${enc('files(id,name)')}` +
  '&supportsAllDrives=true&includeItemsFromAllDrives=true';

if (!snapshotId) console.warn('[Carryover] Copy Sheet Snapshot returned no file id — snapshot patch will no-op; run continues');

return [{ json: {
  setting_tabs: SETTING_TABS, ranges: RANGES, carryover_name: CARRYOVER_NAME,
  live_sheet_id: liveSheetId, snapshot_id: snapshotId, archive_parent: archiveParent,
  live_batchget_url, find_url,
} }];

// Build Snapshot Patch + Carryover — assembles (1) the Sheets batchUpdate body that rewrites
// the snapshot's settings tabs with the PREVIOUS run's settings, and (2) the carry-over JSON
// payload holding the CURRENT live settings for the next archive. See DECISIONS
// ARCHIVE_SNAPSHOT_SETTINGS_CARRYOVER. Never throws (best-effort chain).
//
// Inputs (by name):
//   Plan Settings Carryover — tab list / ids
//   Read Live Settings      — batchGet valueRanges of LIVE config/voices/prompts
//   Read Carryover Content  — previous run's carry-over JSON, or an error item on first run
//
// First run (no carry-over yet): we fall back to the live settings as the patch source, which
// makes the snapshot patch a harmless no-op (the snapshot already holds live settings) and we
// just seed the carry-over file.
const plan = $('Plan Settings Carryover').first().json;
const TABS = plan.setting_tabs;

// LIVE settings → { config:[[...]], voices:[[...]], prompts:[[...]] }
const liveVR = ($('Read Live Settings').first().json || {}).valueRanges || [];
const live = {};
TABS.forEach((t, i) => { live[t] = (liveVR[i] && liveVR[i].values) || []; });

// PREVIOUS run's settings from the carry-over file (defensive about shape / first run)
let prevRaw = null;
try { prevRaw = $('Read Carryover Content').first().json; } catch (e) { prevRaw = null; }
const prev = prevRaw && prevRaw.tabs ? prevRaw.tabs
  : (prevRaw && prevRaw.data && prevRaw.data.tabs ? prevRaw.data.tabs : null);

const usedPrev = !!(prev && TABS.some((t) => Array.isArray(prev[t]) && prev[t].length));
const source = usedPrev ? prev : live;

// Pad each tab to a generous fixed block so a SHORTER previous table also blanks any trailing
// rows the live copy carried — no separate batchClear node needed.
const PAD_ROWS = 200;
const COLS = { config: 2, voices: 26, prompts: 3 };
const endCol = (n) => { let s = ''; let x = n; while (x > 0) { const m = (x - 1) % 26; s = String.fromCharCode(65 + m) + s; x = Math.floor((x - 1) / 26); } return s; };
function pad(values, cols) {
  const out = [];
  for (let r = 0; r < PAD_ROWS; r++) {
    const row = (values[r] || []).slice(0, cols);
    while (row.length < cols) row.push('');
    out.push(row);
  }
  return out;
}
const data = TABS.map((t) => {
  const cols = COLS[t] || 26;
  return { range: `${t}!A1:${endCol(cols)}${PAD_ROWS}`, majorDimension: 'ROWS', values: pad(source[t] || [], cols) };
});

const carryover_doc = {
  saved_at_archive: $('Plan Archive').first().json.archive_name,
  saved_for_run: ($('Once Per Run').first().json.new_file_names || []).join(','),
  tabs: live,
};

console.log(`[Carryover] snapshot patch source = ${usedPrev ? 'previous-run carry-over' : 'live (first run / no carry-over — no-op)'}`);
return [{ json: { snapshot_patch: { valueInputOption: 'RAW', data }, carryover_doc, used_prev: usedPrev } }];

// Plan Subfolders — emits one item per archive subfolder we need to create.
// Skips any src_key that has no files in the plan (e.g. if 04_vtt had 0 leftovers,
// we don't create an empty 04_vtt subfolder).
const plan = $('Plan Archive').first().json;
const rootId = $('Create Archive Root').first().json.id;
const presentKeys = new Set(plan.files.map(f => f.src_key));
const order = ['01_input', '02_output', '03_full', '04_vtt'];
return order
  .filter(k => presentKeys.has(k))
  .map(k => ({ json: { name: k, parent: rootId } }));

// Plan Moves — pairs each file in the plan with the just-created destination
// subfolder ID. Emits one item per file. Move File HTTP node fires per item.
const planSubInputs = $('Plan Subfolders').all().map(i => i.json);
const createdSubs = $('Create Subfolder').all().map(i => i.json);

// Pair by index: Create Subfolder fires once per Plan Subfolders item in order.
const subMap = {};
for (let i = 0; i < planSubInputs.length; i++) {
  if (!createdSubs[i] || !createdSubs[i].id) {
    console.error(`[Archive] missing subfolder response for ${planSubInputs[i].name}`);
    continue;
  }
  subMap[planSubInputs[i].name] = createdSubs[i].id;
}

const plan = $('Plan Archive').first().json;
const out = [];
for (const f of plan.files) {
  const dest = subMap[f.src_key];
  if (!dest) {
    console.error(`[Archive] no destination subfolder for ${f.name} (src_key=${f.src_key}) — skipping`);
    continue;
  }
  out.push({ json: { file_id: f.id, name: f.name, src_folder: f.src_folder, dest_folder: dest } });
}
console.log(`[Archive] planned ${out.length} moves`);
return out;

// Pass Lessons (after Archive) — re-emits the original Parse Filename items so
// Execute W1 fan-out works as before (one item per dropped file).
// Same idiom as the existing Pass Lessons (after W1/W2/W3) nodes.
return $('Parse Filename').all().map(i => ({ json: i.json }));

// Collapse downstream item stream back to one item per source lesson.
// Execute Workflow with mode=each emits aggregated sub-workflow output, which
// would multiply downstream item count and make the next Execute Workflow node
// call the sub-workflow far more times than intended. Re-emit Parse Filename items
// so the count is stable at N (= number of dropped files).
return $('Parse Filename').all().map(i => ({ json: i.json }));

// Build one Slack message per Parse Filename item (one per source audio file).
// Reads config from $('Read Config') and per-lesson needs_attention stats from $('Read Localizations').
// Emits { channel, text } — Slack Notify uses mrkdwn (clickable <url|label> links).
const cfg = {};
$('Read Config').all().forEach(i => { if (i.json && i.json.key) cfg[i.json.key] = i.json.value; });

const fullFolder = cfg.drive_output_full_folder_id || cfg.drive_output_folder_id;
const segmentsFolder = cfg.drive_output_folder_id;
const vttFolder  = cfg.drive_output_vtt_folder_id;
const regenUrl   = cfg.w_regen_workflow_url;
const channel    = cfg.slack_channel;
if (!channel) throw new Error('slack_channel missing from config sheet (set to channel ID like C01234ABCDE)');

const fullUrl     = fullFolder     ? `https://drive.google.com/drive/folders/${fullFolder}`     : null;
const segmentsUrl = segmentsFolder ? `https://drive.google.com/drive/folders/${segmentsFolder}` : null;
const vttUrl      = vttFolder      ? `https://drive.google.com/drive/folders/${vttFolder}`      : null;
const activeLangs = (cfg.active_langs || 'de,es,fr,it,pl,pt,tr').split(',').map(s => s.trim()).filter(Boolean);

const allLocs = $('Read Localizations').all().map(i => i.json || {});
const isFlagged = v => v === true || v === 'TRUE' || v === 'true';

function statsForLesson(lesson_id) {
  const rows = allLocs.filter(r => (r.segment_id || '').startsWith(lesson_id + '_'));
  const total = rows.length;
  const flagged = rows.filter(r => isFlagged(r.needs_attention)).length;
  const pct = total > 0 ? Math.round((flagged / total) * 100) : null;
  return { total, flagged, pct };
}

function buildMessage(p) {
  const lesson_id = p.json.lesson_id;
  const filename  = p.json.filename;
  const { total, flagged, pct } = statsForLesson(lesson_id);
  const naLine = pct === null ? 'n/a' : `${pct}% (${flagged} / ${total})`;

  const lines = [
    ':white_check_mark: *Dubbing complete*',
    '',
    `*Lesson:* ${lesson_id}`,
    `*Source file:* ${filename}`,
    `*Languages:* ${activeLangs.length} (${activeLangs.join(', ')})`,
    `*Needs attention:* ${naLine}`,
  ];
  if (fullUrl || segmentsUrl || vttUrl || regenUrl) lines.push('');
  if (fullUrl)     lines.push(`:file_folder: <${fullUrl}|Full audio (per-lang)>`);
  if (segmentsUrl) lines.push(`:musical_note: <${segmentsUrl}|Per-segment audio>`);
  if (vttUrl)      lines.push(`:closed_book: <${vttUrl}|VTT subtitles>`);
  if (regenUrl)    lines.push(`:wrench: <${regenUrl}|Regen Segments>`);

  return { json: { channel, text: lines.join('\n') } };
}

return $('Parse Filename').all().map(buildMessage);

// Prepare the two config rows that scope the cooperative kill-switch to THIS run (W_Master,
// runs right after Once Per Run). Emits two items that the following Sheets appendOrUpdate
// node writes to the config tab (matching on `key`):
//   localization_run_token   = archive_run_at  → identifies the current run
//   localization_abort_token = ''              → clears any stale stop from a previous run
//
// A checkpoint aborts only when localization_abort_token === localization_run_token (both
// non-empty). Resetting abort_token here guarantees a fresh run is never blocked by an old stop.
const run = $('Once Per Run').first().json || {};
const runToken = (run.archive_run_at || '').toString();
if (!runToken) {
  console.warn('Prepare Run Token: Once Per Run produced no archive_run_at — run_token will be empty');
}
return [
  { json: { key: 'localization_run_token', value: runToken } },
  { json: { key: 'localization_abort_token', value: '' } },
];

// Build the "localization started" Slack message (W_Master, fires right after Once Per Run,
// before the archive chain). Emits ONE item { channel, text, blocks } consumed by an HTTP
// Request node that POSTs to Slack chat.postMessage (blocks need the raw API — the native
// Slack node can't author a Block Kit `confirm` dialog by hand).
//
// The message carries an interactive danger button "🛑 Зупинити локалізацію" with a native
// Slack confirm dialog. The button's `value` is the run_token (= Once Per Run's archive_run_at);
// clicking it routes to W_Abort, which writes localization_abort_token = run_token. Cooperative
// checkpoints (W3 Dispatch) compare the two tokens and halt the run.
//
// Reads:
//   $('Read Config (Start)').all()  — slack_channel
//   $('Once Per Run').first().json  — archive_run_at (run_token), new_file_names
const cfg = {};
$('Read Config (Start)').all().forEach(i => { if (i.json && i.json.key) cfg[i.json.key] = i.json.value; });

const channel = cfg.slack_channel;
if (!channel) {
  // Don't hard-fail the run just because Slack isn't configured — skip the heads-up message.
  console.log('Build Started Slack: slack_channel missing — skipping start notification');
  return [];
}

const run = $('Once Per Run').first().json || {};
const runToken = (run.archive_run_at || '').toString();
const names = (run.new_file_names || []).filter(Boolean);
const filesLine = names.length ? names.join(', ') : '(unknown)';

const headerText = [
  ':rocket: *Localization started*',
  '',
  `*Source file(s):* ${filesLine}`,
  '',
  ":warning: Don't edit Drive or Sheets until localization finishes.",
].join('\n');

const blocks = [
  { type: 'section', text: { type: 'mrkdwn', text: headerText } },
  {
    type: 'actions',
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: '🛑 Stop localization', emoji: true },
        style: 'danger',
        action_id: 'abort_localization',
        value: runToken,
        confirm: {
          title: { type: 'plain_text', text: 'Stop localization?' },
          text: { type: 'mrkdwn', text: "All processes of the current run will stop at the next checkpoint. The current language will finish generating first. This can't be undone." },
          confirm: { type: 'plain_text', text: 'Stop' },
          deny: { type: 'plain_text', text: 'Cancel' },
          style: 'danger',
        },
      },
    ],
  },
];

// `text` is the notification/fallback string Slack shows in push/preview when blocks can't render.
return [{ json: { channel, text: "Localization started — don't touch Drive", blocks } }];

// Single-flight guard (W_Master, runs right after Once Per Run, BEFORE the archive/clear chain).
// Prevents a duplicate Drive trigger (n8n googleDriveTrigger can fire several times for ONE
// upload) from starting a SECOND run that would Clear Sheet Tabs mid-write of the first run —
// the root cause of the 2026-06-16 som_th_3 stomp (pl/pt fragmented, it/tr lost).
//
// A run is ACTIVE (so THIS execution must bail) when the config run_token:
//   - is set, AND
//   - was NOT aborted    (abort_token     !== run_token), AND
//   - has NOT completed  (completed_token !== run_token), AND
//   - is still fresh     (age < stale window — a crashed run never marks completion, so the
//                         freshness escape prevents it from wedging the pipeline forever).
// W3 writes localization_run_completed_token = run_token on the final language (is_last_lang),
// so a normally-finished run releases the lock immediately — no time window needed in the happy path.
const cfg = {};
$('Read Config (Guard)').all().forEach(i => { if (i.json && i.json.key) cfg[i.json.key] = i.json.value; });

const runToken       = (cfg.localization_run_token || '').toString().trim();
const abortToken     = (cfg.localization_abort_token || '').toString().trim();
const completedToken = (cfg.localization_run_completed_token || '').toString().trim();
const STALE_MIN      = parseFloat(cfg.localization_stale_run_minutes) || 60;

let ageMin = Infinity;
const started = Date.parse(runToken);            // run_token is an ISO timestamp (archive_run_at)
if (!isNaN(started)) ageMin = (Date.now() - started) / 60000;

const runActive = !!(
  runToken &&
  abortToken     !== runToken &&
  completedToken !== runToken &&
  ageMin < STALE_MIN
);

const once = $('Once Per Run').first().json || {};
if (runActive) {
  console.warn(`W_Master single-flight: run ${runToken} still active (age ${ageMin.toFixed(1)}m < ${STALE_MIN}m, not aborted, not completed) — IGNORING duplicate trigger for: ${(once.new_file_names||[]).join(', ') || '(unknown)'}`);
} else {
  console.log(`W_Master single-flight: clear to start (prev run_token=${runToken||'(none)'}, completed=${completedToken||'(none)'}, age=${ageMin===Infinity?'n/a':ageMin.toFixed(1)+'m'}).`);
}
// Pass Once Per Run's payload through unchanged so the downstream nodes on the "not active"
// branch (Read Config Archive / Start) receive the same item shape they did before the guard.
return [{ json: { ...once, run_active: runActive, guard_age_min: ageMin, guard_run_token: runToken } }];
